func fetch(ctx context.Context, url string) (string, error) {
    ch := make(chan string)              // небуферизованный
    go func() { ch <- slowGet(url) }()   // заблокируется навсегда после таймаута
    select {
    case res := <-ch:
        return res, nil
    case <-ctx.Done():
        return "", ctx.Err()
    }
}

